## Why This Is Asked

This problem tests advanced dynamic programming: partitioning with a non-trivial segment cost that depends on min and max, requiring careful state design and in-loop maintenance of subproblem results. It also validates producing both memoized and iterative solutions and analyzing time/space trade-offs.

## Key Concepts

- DP with partition states
- In-loop maintenance of running min and max
- Top-down memoization vs bottom-up tabulation
- Time complexity: O(D*N^2); Space: O(D*N)

## Code Example

```javascript
// Top-down memoized
function minCost(A, D){
  const N = A.length;
  const memo = Array.from({length:D+1}, ()=> Array(N).fill(null));
  function solve(d, i){
    if (d === 1){
      let mn = Infinity, mx = -Infinity;
      for (let k = 0; k <= i; k++){ mn = Math.min(mn, A[k]); mx = Math.max(mx, A[k]); }
      return mn * mx;
    }
    if (memo[d][i] != null) return memo[d][i];
    let mn = Infinity, mx = -Infinity; let best = Infinity;
    for (let j = i; j >= d-1; j--){
      mn = Math.min(mn, A[j]); mx = Math.max(mx, A[j]);
      best = Math.min(best, solve(d-1, j-1) + mn*mx);
    }
    memo[d][i] = best; return best;
  }
  return solve(D, N-1);
}

// Bottom-up
function minCostBottom(A, D){
  const N = A.length, INF = 1e18;
  const dp = Array.from({length:D+1}, ()=> Array(N).fill(INF));
  // base: d = 1
  for (let i = 0; i < N; i++){
    let mn = A[i], mx = A[i];
    for (let j = i; j >= 0; j--){
      mn = Math.min(mn, A[j]); mx = Math.max(mx, A[j]);
      if (j === 0) dp[1][i] = Math.min(dp[1][i], mn*mx);
    }
  }
  for (let d = 2; d <= D; d++){
    for (let i = d-1; i < N; i++){
      let mn = A[i], mx = A[i];
      for (let j = i; j >= d-1; j--){
        mn = Math.min(mn, A[j]); mx = Math.max(mx, A[j]);
        dp[d][i] = Math.min(dp[d][i], dp[d-1][j-1] + mn*mx);
      }
    }
  }
  return dp[D][N-1];
}
```

## Why This Is Asked

This question tests the ability to design augmented self-balancing BSTs for dynamic range queries—a common requirement in analytics and data processing applications.

## Key Concepts

- **AVL balancing**: Maintaining height balance factor (|left.height - right.height| ≤ 1) through rotations
- **Augmented BST data**: Storing additional aggregate information (cnt, sum) at each node
- **Range query on BST**: Using the BST property to efficiently prune irrelevant subtrees
- **Correctness and complexity analysis**: Ensuring O(log n) operations and verifying invariants

## Code Example

```javascript
class Node {
  constructor(key) {
    this.key = key;
    this.cnt = 1;
    this.height = 1;
    this.left = null;
    this.right = null;
    this.sum = key;
  }
}

function getHeight(node) { return node ? node.height : 0; }
function getSum(node) { return node ? node.sum : 0; }
function update(node) {
  node.height = 1 + Math.max(getHeight(node.left), getHeight(node.right));
  node.sum = getSum(node.left) + node.key * node.cnt + getSum(node.right);
}

function rightRotate(y) {
  const x = y.left;
  y.left = x.right;
  x.right = y;
  update(y);
  update(x);
  return x;
}

function rangeSum(node, a, b) {
  if (!node) return 0;
  if (node.key < a) return rangeSum(node.right, a, b);
  if (node.key > b) return rangeSum(node.left, a, b);
  return getSum(node.left) + node.key * node.cnt + rangeSum(node.right, a, b);
}
```

